class Logger {
public:
  bool shouldPrintMessage(int timestamp, const std::string& message);
};

questions.modelAnswer:
#include <deque>
#include <string>
#include <unordered_map>
#include <utility>

class Logger {
  static constexpr int kWindow = 10;
  std::unordered_map<std::string, int> nextAllowed_;     // message -> first time it may print again
  std::deque<std::pair<int, std::string>> expiry_;       // (expiry time, message), in time order
public:
  bool shouldPrintMessage(int timestamp, const std::string& message) {
    // Drop entries that already expired so memory stays O(messages in the last 10 s).
    while (!expiry_.empty() && expiry_.front().first <= timestamp) {
      auto& [t, msg] = expiry_.front();
      auto it = nextAllowed_.find(msg);
      if (it != nextAllowed_.end() && it->second == t) nextAllowed_.erase(it);
      expiry_.pop_front();
    }
    if (nextAllowed_.count(message)) return false;       // printed less than 10 s ago
    nextAllowed_[message] = timestamp + kWindow;
    expiry_.emplace_back(timestamp + kWindow, message);
    return true;
  }
};

import heapq


class AuthenticationManager:
    def __init__(self, time_to_live: int):
        self.ttl = time_to_live
        self.expiry = {}   # token -> expiry time (the live one)
        self.heap = []     # (expiry, token); may hold stale entries after renew

    def _purge(self, now: int) -> None:
        # Lazy deletion: pop everything that expired; skip entries made stale by renew.
        while self.heap and self.heap[0][0] <= now:
            t, tok = heapq.heappop(self.heap)
            if self.expiry.get(tok) == t:
                del self.expiry[tok]

    def generate(self, token_id: str, current_time: int) -> None:
        self._purge(current_time)
        exp = current_time + self.ttl
        self.expiry[token_id] = exp
        heapq.heappush(self.heap, (exp, token_id))

    def renew(self, token_id: str, current_time: int) -> None:
        self._purge(current_time)          # a token expiring exactly now is already dead
        if token_id in self.expiry:
            exp = current_time + self.ttl
            self.expiry[token_id] = exp
            heapq.heappush(self.heap, (exp, token_id))

    def countUnexpiredTokens(self, current_time: int) -> int:
        self._purge(current_time)
        return len(self.expiry)

