public:
  bool insert(int val);
  bool remove(int val);
  int getRandom();
};

questions.modelAnswer:
#include <random>
#include <unordered_map>
#include <vector>

class RandomizedSet {
  std::vector<int> vals_;                     // dense array: uniform pick by index
  std::unordered_map<int, int> pos_;          // value -> index in vals_
  std::mt19937 rng_{std::random_device{}()};
public:
  bool insert(int val) {
    if (pos_.count(val)) return false;
    pos_[val] = (int)vals_.size();
    vals_.push_back(val);
    return true;
  }
  bool remove(int val) {
    auto it = pos_.find(val);
    if (it == pos_.end()) return false;
    int i = it->second, last = vals_.back();
    vals_[i] = last;                          // move the last element into the hole
    pos_[last] = i;                           // update its index BEFORE erasing val
    vals_.pop_back();
    pos_.erase(val);                          // erase by key: `it` may be stale if last == val
    return true;
  }
  int getRandom() {
    return vals_[std::uniform_int_distribution<size_t>(0, vals_.size() - 1)(rng_)];
  }
};

