#include <random>
#include <vector>

class Solution {
  const std::vector<int>& nums_;          // O(1) extra memory: no index map
  std::mt19937 rng_{std::random_device{}()};
public:
  explicit Solution(const std::vector<int>& nums) : nums_(nums) {}

  // Reservoir sampling with k = 1: the c-th match replaces the answer with probability 1/c.
  int pick(int target) {
    int chosen = -1, count = 0;
    for (int i = 0; i < (int)nums_.size(); ++i) {
      if (nums_[i] != target) continue;
      ++count;
      if (std::uniform_int_distribution<int>(1, count)(rng_) == 1) chosen = i;
    }
    return chosen;
  }
};

#include <string>

int value(char c) {
  switch (c) {
    case 'I': return 1;    case 'V': return 5;    case 'X': return 10;
    case 'L': return 50;   case 'C': return 100;  case 'D': return 500;
    case 'M': return 1000;
  }
  return 0;
}

int romanToInt(const std::string& s) {
  int total = 0;
  for (size_t i = 0; i < s.size(); ++i) {
    int v = value(s[i]);
    // A smaller symbol before a larger one is subtracted (IV = 4, CM = 900).
    if (i + 1 < s.size() && v < value(s[i + 1])) total -= v;
    else total += v;
  }
  return total;
}

#include <vector>

// O(1) extra memory: row 0 and column 0 store the "zero this row/column" markers.
void setZeroes(std::vector<std::vector<int>>& m) {
  const int R = m.size(), C = m[0].size();
  bool firstRow = false, firstCol = false;          // the markers' own cells need separate flags
  for (int c = 0; c < C; ++c) if (m[0][c] == 0) firstRow = true;
  for (int r = 0; r < R; ++r) if (m[r][0] == 0) firstCol = true;

  for (int r = 1; r < R; ++r)
    for (int c = 1; c < C; ++c)
      if (m[r][c] == 0) m[r][0] = m[0][c] = 0;      // mark row r and column c

  for (int r = 1; r < R; ++r)                       // fill the inner part from the markers
    for (int c = 1; c < C; ++c)
      if (m[r][0] == 0 || m[0][c] == 0) m[r][c] = 0;

  if (firstRow) for (int c = 0; c < C; ++c) m[0][c] = 0;   // markers last, or they spread
  if (firstCol) for (int r = 0; r < R; ++r) m[r][0] = 0;
}

from typing import Iterable


def is_toeplitz(mat: list[list[int]]) -> bool:
    # Every cell must equal its upper-left neighbour.
    for r in range(1, len(mat)):
        for c in range(1, len(mat[0])):
            if mat[r][c] != mat[r - 1][c - 1]:
                return False
    return True


def is_toeplitz_stream(rows: Iterable[list[int]]) -> bool:
    # Follow-up: rows arrive one at a time and only one row fits in memory.
    # Row r is Toeplitz-consistent with row r-1 iff row[1:] == prev[:-1].
    prev = None
    for row in rows:
        if prev is not None and row[1:] != prev[:-1]:
            return False
        prev = row
    return True

#include <algorithm>
#include <map>
#include <numeric>
#include <utility>
#include <vector>

// Points are distinct, integer coordinates. O(n^2 log n) with an ordered map.
int maxPoints(const std::vector<std::vector<int>>& pts) {
  const int n = pts.size();
  if (n <= 2) return n;
  int best = 0;
  for (int i = 0; i < n; ++i) {
    std::map<std::pair<int, int>, int> slopes;   // reduced direction (dy, dx) -> count
    for (int j = i + 1; j < n; ++j) {            // lines through i that use later points
      int dx = pts[j][0] - pts[i][0], dy = pts[j][1] - pts[i][1];
      int g = std::gcd(dx, dy);                  // exact: no floating-point slopes
      dx /= g; dy /= g;
      if (dx < 0 || (dx == 0 && dy < 0)) { dx = -dx; dy = -dy; }   // one canonical sign
      best = std::max(best, ++slopes[{dy, dx}]);
    }
  }
  return best + 1;                               // + point i itself
}
